  title: string;
  favicon?: string;
  snippet: string;
  origin: SourceOrigin;
};

export type ComponentStatus = "streaming" | "ready" | "invalid";

export type TextPart = { id: string; type: "text"; text: string };
export type ThinkingPart = { id: string; type: "thinking"; text: string; done: boolean; durationMs?: number };
export type ComponentPart = {
  id: string;
  type: "component";
  name: string;
  props: unknown;
  status: ComponentStatus;
  fallbackText: string;
  error?: string;
};
export type ImagePart = { id: string; type: "image"; uri: string; width?: number; height?: number };
export type SourcesPart = { id: string; type: "sources"; sources: Source[] };
export type UiEventPart = {
  id: string;
  type: "ui_event";
  componentId: string;
  component: string;
  action: string;
  label: string;
  payload?: Record<string, unknown>;
};

export type Part = TextPart | ThinkingPart | ComponentPart | ImagePart | SourcesPart | UiEventPart;

export type ReplyMeta = {
  modelRef: string;
  levelRequested: string;
  levelSent: string;
  reasoningTokens: number;
  kind?: "report";
};

export type MessageStatus = "streaming" | "done" | "stopped" | "error";

export type Message = {
  id: string;
