  title: z.string().optional(),
  location: z.string(),
  date: z.string(),
  movies: z
    .array(
      z.object({
        id,
        title: z.string(),
        year: z.number().int(),
        rating: z.string(),
        runtime: z.number().int().positive(),
        genres: z.array(z.string()),
        score: z.number().min(0).max(10),
        showtimes: z.array(
          z.object({
            theatreId: id,
            theatre: z.string(),
            distanceKm: z.number(),
            format: z.enum(["Standard", "IMAX", "Dolby", "3D"]),
