  title: z.string().optional(),
  center: z.object({ lat: z.number(), lng: z.number(), label: z.string() }),
  places: z
    .array(
      z.object({
        id,
        name: z.string(),
        subtitle: z.string().optional(),
        lat: z.number(),
        lng: z.number(),
        distanceKm: z.number().optional(),
      }),
