function subagents(stage: "plan" | "run" | "cancel"): Script {
  if (stage === "plan") {
    return {
      difficulty: "hard",
      ops: [
        think("Three independent questions plus verification. Parallel(4) fits within depth 1 and budget."),
        say("This splits cleanly into parallel work. Here's the plan. Approve it and the workers start."),
        ui("SubagentPlan", fx.phonePlan, "Plan: four workers for cameras, battery, prices and verification. Estimated cost $0.08.", 900),
      ],
    };
  }
  if (stage === "cancel") {
    return { difficulty: "easy", ops: [say("Cancelled. Nothing ran and nothing was charged to your key.")] };
  }
  const total = Math.max(...fx.phoneTimeline.runs.map((r) => r.durationMs));
  return {
    difficulty: "hard",
    ops: [
      say("Workers are running. You can cancel any of them."),
      ui("SubagentTimeline", fx.phoneTimeline, "Four workers: camera, battery, prices, verification.", 400),
      { op: "wait", ms: total + 500 },
      say(
        "Here's how they compare. One worker couldn't reach carrier pages, so trade-in offers are missing and prices are manufacturer list prices.",
      ),
      ui("Compare", fx.phoneCompare, fx.phoneCompare.verdict ?? "Comparison of Pixel 11 and iPhone 17."),
      { op: "sources", sources: fx.phoneSources },
    ],
  };
}

function memory(text: string, ctx: ScriptContext): Script {
  if (ctx.incognito) {
    return { difficulty: "easy", ops: [say("Got it for this chat. It's incognito, so I won't save anything to memory.")] };
  }
  if (!ctx.memoryEnabled) {
    return { difficulty: "easy", ops: [say("Got it for this chat. Memory is turned off in Settings, so I won't keep it afterwards.")] };
  }
  const gate = decisions.memoryGate(text);
  const auto = gate.confidence > 0.85;
  return {
    difficulty: "easy",
    ops: [
      say(auto ? "Got it. I'll keep that in mind in future chats." : "Got it. Want me to remember this across chats?"),
      ui(
        "MemoryConfirm",
        { text: gate.choice.text, category: gate.choice.category, scope: gate.choice.scope, confidence: gate.confidence },
        `Memory: ${gate.choice.text}`,
        300,
      ),
    ],
  };
}

