/** Web / Android: a floating glass pill that mirrors the iOS 26 tab bar. */
function GlassTabBar({ state, navigation }: BottomTabBarProps) {
  const insets = useSafeAreaInsets();
  return (
    <View
      pointerEvents="box-none"
      style={{ position: "absolute", left: 0, right: 0, bottom: Math.max(insets.bottom, 12), alignItems: "center" }}
    >
      <Glass radius={999} style={{ width: "92%", maxWidth: 420 }}>
        <View accessibilityRole="tablist" className="flex-row p-1">
          {state.routes.map((route, i) => {
            const tab = tabs.find((t) => t.name === route.name);
            if (!tab) return null;
            const active = state.index === i;
            return (
              <Tap
                key={route.key}
                haptic
                accessibilityRole="tab"
                accessibilityState={{ selected: active }}
                accessibilityLabel={tab.title}
                onPress={() => {
                  const event = navigation.emit({ type: "tabPress", target: route.key, canPreventDefault: true });
                  if (!active && !event.defaultPrevented) navigation.navigate(route.name);
                }}
                className={`flex-1 items-center gap-0.5 rounded-full py-1.5 ${active ? "bg-white/10" : ""}`}
              >
                <Icon name={active ? tab.iconActive : tab.icon} size={21} color={active ? colors.primary : colors.textMuted} />
                <Text weight={active ? "bold" : "medium"} className={`text-[11px] ${active ? "text-primary" : "text-ink-muted"}`}>
                  {tab.title}
                </Text>
              </Tap>
            );
          })}
        </View>
      </Glass>
    </View>
  );
}

export function AppTabs() {
  return (
    <Tabs
      tabBar={(props) => <GlassTabBar {...props} />}
      screenOptions={{ headerShown: false, sceneStyle: { backgroundColor: colors.background } }}
    >
      {tabs.map((t) => (
        <Tabs.Screen key={t.name} name={t.name} options={{ title: t.title }} />
      ))}
    </Tabs>
  );
}

