export function formatMoney(n: number, currency = "USD"): string {
  return new Intl.NumberFormat("en-US", { style: "currency", currency, maximumFractionDigits: 0 }).format(n);
}

import { Fragment, type ReactNode } from "react";
import { Text as RNText, View } from "react-native";
import { Text } from "@/components/ui/Text";

/** Drops a trailing unmatched `**` so half-streamed bold doesn't flash raw asterisks. */
function balance(text: string): string {
  const count = (text.match(/\*\*/g) ?? []).length;
  if (count % 2 === 0) return text;
  const i = text.lastIndexOf("**");
  return text.slice(0, i) + text.slice(i + 2);
}

function inline(text: string, keyBase: string): ReactNode[] {
  return balance(text)
    .split(/(\*\*[^*]+\*\*|`[^`]+`|\[\d+\])/g)
    .filter(Boolean)
    .map((seg, i) => {
      const key = `${keyBase}-${i}`;
      if (seg.startsWith("**") && seg.endsWith("**")) {
        return (
          <RNText key={key} className="font-body-bold text-ink">
            {seg.slice(2, -2)}
          </RNText>
        );
      }
      if (seg.startsWith("`") && seg.endsWith("`")) {
        return (
          <RNText key={key} className="font-body-medium text-[14px] text-primary-strong">
            {seg.slice(1, -1)}
          </RNText>
        );
      }
      if (/^\[\d+\]$/.test(seg)) {
        return (
          <RNText key={key} accessibilityLabel={`Source ${seg.slice(1, -1)}`} className="font-body-bold text-[11px] text-primary">
            {` ${seg.slice(1, -1)}`}
          </RNText>
        );
      }
      return <Fragment key={key}>{seg}</Fragment>;
    });
}

/** Just enough Markdown for chat: paragraphs, ### headings, bullets, numbered lists, bold, code, [n] citations. */
export function Markdown({ text }: { text: string }) {
  const blocks = text.split(/\n{2,}/);
  return (
    <View className="gap-3">
      {blocks.map((block, bi) => {
        const lines = block.split("\n");
        if (lines.every((l) => /^(-|\d+\.)\s/.test(l))) {
          return (
            <View key={bi} className="gap-1.5">
              {lines.map((l, li) => {
                const numbered = /^\d+\./.test(l);
                const marker = numbered ? l.match(/^\d+\./)![0] : "•";
                return (
                  <View key={li} className="flex-row pr-2">
                    <Text muted weight={numbered ? "bold" : "regular"} className="w-5 text-base leading-[25px]">
                      {marker}
                    </Text>
                    <Text className="flex-1 text-base leading-[25px]">{inline(l.replace(/^(-|\d+\.)\s/, ""), `${bi}-${li}`)}</Text>
                  </View>
                );
              })}
            </View>
          );
        }
        return (
          <View key={bi} className="gap-1.5">
            {lines.map((l, li) =>
              l.startsWith("### ") ? (
                <Text key={li} weight="bold" className={`text-[17px] leading-6 ${bi > 0 ? "mt-2" : ""}`}>
                  {l.slice(4)}
                </Text>
              ) : l.trim() ? (
                <Text key={li} className="text-base leading-[25px]">
                  {inline(l, `${bi}-${li}`)}
                </Text>
              ) : null,
            )}
          </View>
        );
      })}
    </View>
  );
}

import { useRef, useState } from "react";
import { PanResponder, View } from "react-native";
import { colors } from "@/lib/theme";

type Props = {
  value: number;
  min: number;
  max: number;
  step: number;
  onChange: (v: number) => void;
  accessibilityLabel: string;
  format?: (v: number) => string;
};

const HANDLE = 28;

/** Draggable track. Snaps to `step`; keyboard/VoiceOver adjust via accessibility actions. */
export function Slider({ value, min, max, step, onChange, accessibilityLabel, format }: Props) {
  const [width, setWidth] = useState(0);
  const startX = useRef(0);
  const latest = useRef({ width, value, onChange });
  latest.current = { width, value, onChange };

  const toValue = (x: number) => {
    const w = Math.max(1, latest.current.width - HANDLE);
    const ratio = Math.min(1, Math.max(0, (x - HANDLE / 2) / w));
    const raw = min + ratio * (max - min);
    return Math.min(max, Math.max(min, Math.round(raw / step) * step));
  };

  const responder = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponderCapture: (_e, g) => Math.abs(g.dx) > Math.abs(g.dy),
      onPanResponderTerminationRequest: () => false,
      onPanResponderGrant: (e) => {
        startX.current = e.nativeEvent.locationX;
        const v = toValue(startX.current);
        if (v !== latest.current.value) latest.current.onChange(v);
      },
      onPanResponderMove: (_e, g) => {
        const v = toValue(startX.current + g.dx);
        if (v !== latest.current.value) latest.current.onChange(v);
      },
    }),
  ).current;

  const ratio = (value - min) / (max - min || 1);
  const left = ratio * Math.max(0, width - HANDLE);

  return (
    <View
      accessible
      accessibilityRole="adjustable"
      accessibilityLabel={accessibilityLabel}
      accessibilityValue={{ min, max, now: value, text: format?.(value) }}
      accessibilityActions={[{ name: "increment" }, { name: "decrement" }]}
      onAccessibilityAction={(e) => {
        if (e.nativeEvent.actionName === "increment") onChange(Math.min(max, value + step));
        if (e.nativeEvent.actionName === "decrement") onChange(Math.max(min, value - step));
      }}
      onLayout={(e) => setWidth(e.nativeEvent.layout.width)}
      style={{ height: 36, justifyContent: "center", cursor: "pointer" } as object}
      {...responder.panHandlers}
    >
      <View pointerEvents="none" style={{ height: 6, borderRadius: 3, backgroundColor: colors.raised, marginHorizontal: HANDLE / 2 }}>
        <View style={{ width: left, height: 6, borderRadius: 3, backgroundColor: colors.primary }} />
      </View>
      <View
        pointerEvents="none"
        style={{
          position: "absolute",
          left,
          width: HANDLE,
          height: HANDLE,
          borderRadius: HANDLE / 2,
          backgroundColor: "#FFFFFF",
          borderWidth: 4,
          borderColor: colors.primary,
        }}
      />
    </View>
  );
}

import { View } from "react-native";
import Svg, { Circle, Defs, LinearGradient, Path, Rect, Stop } from "react-native-svg";
import { hsl, hueFrom } from "@/lib/theme";
