import { useState } from "react";
import { View } from "react-native";
import Svg, { Circle, G, Line, Path, Rect, Text as SvgText } from "react-native-svg";
import { Icon } from "@/components/ui/Icon";
import { Tap } from "@/components/ui/Tap";
import { Text } from "@/components/ui/Text";
import { ActionButton, GenCard, type GenProps } from "@/genui/kit";
import { colors, fonts } from "@/lib/theme";

const H = 210;

/**
 * Stylised vector map so the mock works offline and on web. MapLibre + OSM tiles replace the SVG layer
 * in the native build; the pin ↔ list sync stays the same.
 */
export function MapCard({ props, emit, busy }: GenProps<"MapCard">) {
  const [w, setW] = useState(0);
  const [selected, setSelected] = useState(props.places[0].id);
  const all = [...props.places, { id: "__home", lat: props.center.lat, lng: props.center.lng }];
  const lats = all.map((p) => p.lat);
  const lngs = all.map((p) => p.lng);
  const pad = 0.18;
  const [minLat, maxLat] = [Math.min(...lats), Math.max(...lats)];
  const [minLng, maxLng] = [Math.min(...lngs), Math.max(...lngs)];
  const dLat = (maxLat - minLat || 0.01) * (1 + pad * 2);
  const dLng = (maxLng - minLng || 0.01) * (1 + pad * 2);
  const x = (lng: number) => ((lng - (minLng - (maxLng - minLng) * pad)) / dLng) * w;
  const y = (lat: number) => H - ((lat - (minLat - (maxLat - minLat) * pad)) / dLat) * H;
  const place = props.places.find((p) => p.id === selected) ?? props.places[0];

  // Toronto's street grid runs about 17° off true north — the map leans with it.
  const streets = Array.from({ length: 16 }, (_, i) => i);

  return (
    <GenCard title={props.title ?? "Map"} subtitle={`Around ${props.center.label}`} icon="map-outline" flush>
      <View onLayout={(e) => setW(e.nativeEvent.layout.width)} style={{ height: H, backgroundColor: "#0D0D10" }}>
        {w > 0 ? (
          <Svg width={w} height={H}>
            <G rotation={-17} origin={`${w / 2}, ${H / 2}`}>
              {streets.map((i) => (
                <Line
                  key={`v${i}`}
                  x1={-w * 0.3 + (i * w * 1.6) / 15}
                  y1={-H}
                  x2={-w * 0.3 + (i * w * 1.6) / 15}
                  y2={H * 2}
                  stroke={i % 5 === 2 ? "#2B2B33" : "#1A1A1F"}
                  strokeWidth={i % 5 === 2 ? 4 : 1.5}
                />
              ))}
              {streets.map((i) => (
                <Line
                  key={`h${i}`}
                  x1={-w}
                  y1={-H * 0.4 + (i * H * 1.8) / 15}
                  x2={w * 2}
                  y2={-H * 0.4 + (i * H * 1.8) / 15}
                  stroke={i % 4 === 1 ? "#2B2B33" : "#1A1A1F"}
                  strokeWidth={i % 4 === 1 ? 4 : 1.5}
                />
              ))}
              <Rect x={w * 0.62} y={H * 0.08} width={w * 0.12} height={H * 0.22} rx={6} fill="#0F1F17" />
            </G>
            <Path d={`M0 ${H * 0.86} C ${w * 0.3} ${H * 0.8}, ${w * 0.6} ${H * 0.92}, ${w} ${H * 0.84} L ${w} ${H} L 0 ${H} Z`} fill="#0B1729" />
            <Circle cx={x(props.center.lng)} cy={y(props.center.lat)} r={16} fill="rgba(59,130,246,0.18)" />
            <Circle cx={x(props.center.lng)} cy={y(props.center.lat)} r={6} fill={colors.primary} stroke="#fff" strokeWidth={2} />
            {props.places.map((p, i) => {
              const on = p.id === selected;
              return (
                <G key={p.id} onPress={() => setSelected(p.id)}>
                  <Circle cx={x(p.lng)} cy={y(p.lat)} r={on ? 14 : 11} fill={on ? colors.primary : colors.raised} stroke={on ? "#fff" : "#52525B"} strokeWidth={on ? 2 : 1} />
                  <SvgText
                    x={x(p.lng)}
                    y={y(p.lat) + 4}
                    fontSize={on ? 12 : 11}
                    fontFamily={fonts.bold}
                    fontWeight="700"
                    fill="#fff"
                    textAnchor="middle"
                  >
                    {String(i + 1)}
                  </SvgText>
                </G>
              );
            })}
          </Svg>
        ) : null}
        <View className="absolute bottom-2 right-3">
          <Text className="text-[10px] text-white/50">© OpenStreetMap contributors</Text>
        </View>
      </View>

      <View className="py-1">
        {props.places.map((p, i) => {
          const on = p.id === selected;
          return (
            <Tap
              key={p.id}
              accessibilityRole="button"
              accessibilityState={{ selected: on }}
              onPress={() => setSelected(p.id)}
              className={`mx-2 flex-row items-center gap-3 rounded-2xl px-2 py-2.5 ${on ? "bg-raised" : ""}`}
            >
              <View className={`h-7 w-7 items-center justify-center rounded-full ${on ? "bg-primary" : "bg-raised"}`}>
                <Text weight="bold" className="text-xs">
                  {i + 1}
                </Text>
              </View>
              <View className="flex-1">
                <Text weight={on ? "bold" : "medium"} className="text-[15px]" numberOfLines={1}>
                  {p.name}
                </Text>
                {p.subtitle ? (
                  <Text muted className="text-[13px]" numberOfLines={1}>
                    {p.subtitle}
                  </Text>
                ) : null}
              </View>
              {p.distanceKm !== undefined ? (
                <Text muted weight="medium" className="text-[13px]">
                  {p.distanceKm} km
                </Text>
              ) : null}
            </Tap>
          );
        })}
      </View>
      <View className="flex-row items-center gap-2 border-t border-hairline px-4 py-3">
        <Icon name="walk-outline" size={16} color={colors.textMuted} />
        <Text muted className="flex-1 text-[13px]">
          About {Math.max(1, Math.round((place.distanceKm ?? 1) * 12))} min walk to {place.name}
        </Text>
        <ActionButton
          size="sm"
          variant="secondary"
          label="Directions"
          disabled={busy}
          onPress={() =>
            emit("directions", `Directions to ${place.name}`, {
              place: place.name,
              minutes: Math.max(1, Math.round((place.distanceKm ?? 1) * 12)),
            })
          }
        />
      </View>
    </GenCard>
  );
}

import { useMemo, useRef, useState } from "react";
import { PanResponder, View } from "react-native";
import Svg, { Circle, Defs, Line, LinearGradient, Path, Stop, Text as SvgText } from "react-native-svg";
import { Slider } from "@/components/ui/Slider";
import { Text } from "@/components/ui/Text";
import { ActionButton, formatMoney, GenCard, Pill, type GenProps } from "@/genui/kit";
import type { CatalogProps } from "@/genui/schemas";
import { colors, fonts } from "@/lib/theme";

const H = 180;
const PAD = { top: 16, right: 52, bottom: 24, left: 4 };

type Series = { name: string; points: { x: number; y: number }[] };

function compound(model: NonNullable<CatalogProps<"Chart">["model"]>, monthly: number): Series[] {
  const rm = model.annualRate / 12;
  const balance: Series = { name: "Balance", points: [] };
  const contributed: Series = { name: "You put in", points: [] };
  for (let year = 0; year <= model.years; year++) {
    const n = year * 12;
    const growth = Math.pow(1 + rm, n);
    const fv = model.principal * growth + (rm === 0 ? monthly * n : monthly * ((growth - 1) / rm));
    balance.points.push({ x: year, y: fv });
    contributed.points.push({ x: year, y: model.principal + monthly * n });
  }
  return [balance, contributed];
}

function compact(n: number, unit: CatalogProps<"Chart">["unit"]) {
  if (unit === "percent") return `${Math.round(n)}%`;
  const prefix = unit === "currency" ? "$" : "";
  if (n >= 1_000_000) return `${prefix}${(n / 1_000_000).toFixed(1)}M`;
  if (n >= 1000) return `${prefix}${Math.round(n / 1000)}k`;
  return `${prefix}${Math.round(n)}`;
}

/** Draggable chart: the slider recomputes the series; drag across the plot to scrub values. */
export function Chart({ props, emit, events, busy }: GenProps<"Chart">) {
  const model = props.model;
  const savedValue = events.at(-1)?.payload?.monthly as number | undefined;
  const [monthly, setMonthly] = useState(savedValue ?? model?.contribution.value ?? 0);
  const [w, setW] = useState(0);
  const [scrub, setScrub] = useState<number | null>(null);

  const series = useMemo(() => (model ? compound(model, monthly) : (props.series ?? [])), [model, monthly, props.series]);
  const main = series[0];
  const xs = main.points.map((p) => p.x);
  const maxY = Math.max(...series.flatMap((s) => s.points.map((p) => p.y))) * 1.08;
  const [minX, maxX] = [Math.min(...xs), Math.max(...xs)];
  const plotW = Math.max(1, w - PAD.left - PAD.right);
  const plotH = H - PAD.top - PAD.bottom;
  const px = (x: number) => PAD.left + ((x - minX) / (maxX - minX || 1)) * plotW;
  const py = (y: number) => PAD.top + plotH - (y / (maxY || 1)) * plotH;

  const path = (s: Series) => s.points.map((p, i) => `${i === 0 ? "M" : "L"}${px(p.x).toFixed(1)} ${py(p.y).toFixed(1)}`).join(" ");
  const area = `${path(main)} L${px(maxX)} ${py(0)} L${px(minX)} ${py(0)} Z`;

  const geom = useRef({ plotW, minX, maxX });
  geom.current = { plotW, minX, maxX };
  const scrubber = useRef(
    PanResponder.create({
      onStartShouldSetPanResponder: () => true,
      onMoveShouldSetPanResponderCapture: (_e, g) => Math.abs(g.dx) > Math.abs(g.dy),
      onPanResponderTerminationRequest: () => false,
      onPanResponderGrant: (e) => setScrub(e.nativeEvent.locationX),
      onPanResponderMove: (e) => setScrub(e.nativeEvent.locationX),
      onPanResponderRelease: () => setScrub(null),
      onPanResponderTerminate: () => setScrub(null),
    }),
  ).current;

  const final = main.points[main.points.length - 1].y;
  const put = series[1]?.points[series[1].points.length - 1].y ?? 0;
  const scrubX =
    scrub === null
      ? null
      : Math.round(geom.current.minX + Math.min(1, Math.max(0, (scrub - PAD.left) / plotW)) * (maxX - minX));
  const scrubPoint = scrubX === null ? null : main.points.find((p) => p.x === scrubX);
  const ticks = [0, 0.5, 1].map((t) => t * maxY);
  const saved = savedValue !== undefined;

  return (
    <GenCard title={props.title} subtitle={props.subtitle} icon="trending-up-outline">
      <View className="mb-2">
        <Text weight="bold" className="text-[30px] leading-9">
          {scrubPoint ? compact(scrubPoint.y, props.unit) : formatMoney(final)}
        </Text>
        <Text muted className="text-[13px]">
          {scrubPoint
            ? `${props.xLabel} ${scrubPoint.x}`
            : model
              ? `After ${model.years} years. You put in ${formatMoney(put)}; growth adds ${formatMoney(final - put)}.`
              : main.name}
        </Text>
      </View>

      <View onLayout={(e) => setW(e.nativeEvent.layout.width)} style={{ height: H }} {...scrubber.panHandlers}>
        {w > 0 ? (
          <Svg width={w} height={H} pointerEvents="none">
            <Defs>
              <LinearGradient id="chartFill" x1="0" y1="0" x2="0" y2="1">
                <Stop offset="0" stopColor={colors.primary} stopOpacity={0.35} />
                <Stop offset="1" stopColor={colors.primary} stopOpacity={0} />
              </LinearGradient>
            </Defs>
            {ticks.map((t) => (
              <G key={t}>
                <Line x1={PAD.left} x2={PAD.left + plotW} y1={py(t)} y2={py(t)} stroke={colors.raised} strokeWidth={1} />
                <SvgText x={w - 4} y={py(t) + 4} fontSize={11} fontFamily={fonts.medium} fill={colors.textFaint} textAnchor="end">
                  {compact(t, props.unit)}
                </SvgText>
              </G>
            ))}
            <Path d={area} fill="url(#chartFill)" />
            {series[1] ? <Path d={path(series[1])} stroke={colors.textMuted} strokeWidth={1.5} strokeDasharray="4 4" fill="none" /> : null}
            <Path d={path(main)} stroke={colors.primary} strokeWidth={2.5} fill="none" />
            {[minX, Math.round((minX + maxX) / 2), maxX].map((x) => (
              <SvgText key={x} x={px(x)} y={H - 6} fontSize={11} fontFamily={fonts.medium} fill={colors.textFaint} textAnchor="middle">
                {String(x)}
              </SvgText>
            ))}
            {scrubPoint ? (
              <G>
                <Line x1={px(scrubPoint.x)} x2={px(scrubPoint.x)} y1={PAD.top} y2={py(0)} stroke={colors.textMuted} strokeWidth={1} />
                <Circle cx={px(scrubPoint.x)} cy={py(scrubPoint.y)} r={5} fill="#fff" stroke={colors.primary} strokeWidth={3} />
              </G>
            ) : (
              <Circle cx={px(maxX)} cy={py(final)} r={4} fill={colors.primary} />
            )}
          </Svg>
        ) : null}
      </View>

      <View className="mt-1 flex-row gap-4">
        <View className="flex-row items-center gap-1.5">
          <View className="h-0.5 w-4 rounded bg-primary" />
          <Text muted className="text-xs">
            {main.name}
          </Text>
        </View>
        {series[1] ? (
          <View className="flex-row items-center gap-1.5">
            <View className="h-0.5 w-4 rounded bg-ink-muted" />
            <Text muted className="text-xs">
              {series[1].name}
            </Text>
          </View>
        ) : null}
      </View>

      {model ? (
        <View className="mt-4 gap-1">
          <View className="flex-row items-baseline justify-between">
            <Text muted className="text-[13px]">
              {model.contribution.label}
            </Text>
            <Text weight="bold" className="text-[17px]">
              {formatMoney(monthly)}
            </Text>
          </View>
          <Slider
            value={monthly}
            min={model.contribution.min}
            max={model.contribution.max}
            step={model.contribution.step}
            onChange={setMonthly}
            accessibilityLabel={model.contribution.label}
            format={(v) => `${formatMoney(v)} a month`}
          />
          <View className="mt-2 flex-row items-center justify-between">
            {saved ? <Pill label={`Saved at ${formatMoney(savedValue)} a month`} tone="success" icon="checkmark" /> : <View />}
            <ActionButton
              size="sm"
              variant={saved ? "secondary" : "primary"}
              label={saved ? "Update plan" : `Use ${formatMoney(monthly)} a month`}
              disabled={busy || (saved && savedValue === monthly)}
              onPress={() =>
                emit("save_plan", `Saved plan at ${formatMoney(monthly)} a month`, {
                  monthly,
                  contribution: formatMoney(monthly),
                  final: formatMoney(final),
                  growth: formatMoney(final - put),
                })
              }
            />
          </View>
        </View>
      ) : null}
    </GenCard>
  );
}

function G({ children }: { children: React.ReactNode }) {
  return <>{children}</>;
}

import { useState } from "react";
import { ScrollView, View } from "react-native";
import { Icon } from "@/components/ui/Icon";
import { Tap } from "@/components/ui/Tap";
import { Text } from "@/components/ui/Text";
import { GenCard, type GenProps } from "@/genui/kit";
import { colors } from "@/lib/theme";

const num = (v: string | number) => (typeof v === "number" ? v : parseFloat(String(v).replace(/[^0-9.-]/g, "")));

/** Sortable table — tap a column header to sort. Scrolls sideways on narrow screens. */
export function Table({ props }: GenProps<"Table">) {
  const [sort, setSort] = useState<{ key: string; dir: 1 | -1 } | null>(null);
  const rows = sort
    ? [...props.rows].sort((a, b) => {
        const col = props.columns.find((c) => c.key === sort.key);
        const av = a[sort.key] ?? "";
        const bv = b[sort.key] ?? "";
        const cmp = col?.numeric ? num(av) - num(bv) : String(av).localeCompare(String(bv));
        return cmp * sort.dir;
      })
    : props.rows;

  return (
    <GenCard title={props.title} icon="grid-outline" flush footer={props.caption ? <Text muted className="text-xs leading-4">{props.caption}</Text> : undefined}>
      <ScrollView horizontal showsHorizontalScrollIndicator={false} contentContainerStyle={{ paddingHorizontal: 16, paddingBottom: 12 }}>
        <View>
          <View className="flex-row border-b border-hairline pb-2">
            {props.columns.map((c, i) => {
              const active = sort?.key === c.key;
              return (
                <Tap
                  key={c.key}
                  accessibilityRole="button"
                  accessibilityLabel={`Sort by ${c.label}`}
                  onPress={() => setSort(active ? { key: c.key, dir: sort.dir === 1 ? -1 : 1 } : { key: c.key, dir: 1 })}
                  className={`flex-row items-center gap-1 ${c.numeric ? "justify-end" : ""}`}
                  style={{ width: i === 0 ? 150 : 104 }}
                >
                  <Text weight="bold" muted={!active} className="text-xs">
                    {c.label}
                  </Text>
                  {active ? <Icon name={sort.dir === 1 ? "arrow-up" : "arrow-down"} size={11} color={colors.text} /> : null}
                </Tap>
              );
            })}
          </View>
          {rows.map((r, ri) => (
            <View key={ri} className={`flex-row py-2.5 ${ri < rows.length - 1 ? "border-b border-hairline" : ""}`}>
              {props.columns.map((c, i) => (
                <Text
                  key={c.key}
                  weight={i === 0 ? "bold" : "regular"}
                  className={`text-sm leading-5 ${c.numeric ? "text-right" : ""}`}
                  style={{ width: i === 0 ? 150 : 104, paddingRight: 8 }}
                >
                  {String(r[c.key] ?? "")}
                </Text>
              ))}
            </View>
          ))}
        </View>
      </ScrollView>
    </GenCard>
  );
}

export function Compare({ props }: GenProps<"Compare">) {
  return (
    <GenCard title={props.title ?? "Comparison"} icon="git-compare-outline">
      <View className="flex-row gap-2">
        {props.items.map((it) => (
