                  {t.model}, about {tokens(t.estTokens)} tokens
                </Text>
              </View>
              {!decided ? <Icon name={on ? "checkmark-circle" : "ellipse-outline"} size={22} color={on ? colors.primary : colors.textFaint} /> : null}
            </Tap>
