/** Plain text for copy, share and speech. Components contribute their fallbackText (PRD §3.3). */
export function plainText(message: Message): string {
  return message.parts
    .map((p) => (p.type === "text" ? p.text.replace(/\*\*/g, "").replace(/\s?\[\d+\]/g, "") : p.type === "component" ? p.fallbackText : ""))
    .filter(Boolean)
    .join("\n\n");
}

const originLabel: Record<Source["origin"], string> = { native: "Model web search", app: "Fetched by Atlas", subagent: "Sub-agent" };

function ActionIcon({ icon, label, onPress, active }: { icon: IconName; label: string; onPress: () => void; active?: boolean }) {
  return (
    <Tap accessibilityRole="button" accessibilityLabel={label} onPress={onPress} hitSlop={4} className="h-8 w-8 items-center justify-center rounded-full">
      <Icon name={icon} size={17} color={active ? colors.primary : colors.textMuted} />
    </Tap>
  );
}

function tokens(n: number) {
  return n >= 1000 ? `${(n / 1000).toFixed(1)}k` : String(n);
}

/** Always last in a reply: stacked favicons, "N sources", then share/save/regenerate/copy (PRD §3.2). */
export function SourcesBar({ message, sources }: { message: Message; sources: Source[] }) {
  const [open, setOpen] = useState(false);
  const [speaking, setSpeaking] = useState(false);
  const saved = useApp((s) => s.savedMessageIds.includes(message.id));
  const toggleSaved = useApp((s) => s.toggleSaved);
  const regenerate = useApp((s) => s.regenerate);
  const showToast = useApp((s) => s.showToast);
  const models = useApp((s) => s.models);
  const busy = useApp((s) => s.streaming !== null);
  const model = message.meta ? findModel(models, message.meta.modelRef) : null;

  useEffect(() => () => void Speech.stop(), []);

  const copy = async () => {
    await Clipboard.setStringAsync(plainText(message));
    showToast("Copied");
  };

  const share = async () => {
    try {
      await Share.share({ message: plainText(message) });
    } catch {
      await copy();
    }
  };

  const speak = () => {
    if (speaking) {
      void Speech.stop();
      setSpeaking(false);
      return;
    }
    setSpeaking(true);
    Speech.speak(plainText(message), { onDone: () => setSpeaking(false), onStopped: () => setSpeaking(false), onError: () => setSpeaking(false) });
  };

  const exportReport = async () => {
    const body = plainText(message);
    const refs = sources.map((s, i) => `[${i + 1}] ${s.title}: ${s.url}`).join("\n");
    await Clipboard.setStringAsync(`${body}\n\n## Sources\n${refs}`);
    showToast("Report copied as Markdown");
  };

  const level = message.meta && message.meta.levelSent !== "off" ? message.meta.levelSent : null;

  return (
    <View className="gap-1.5">
      <View className="flex-row items-center">
        {sources.length > 0 ? (
          <Tap
            accessibilityRole="button"
            accessibilityLabel={`${sources.length} sources`}
            onPress={() => setOpen(true)}
            className="mr-1 flex-row items-center gap-2 rounded-full bg-raised py-1 pl-1 pr-3"
          >
            <View className="flex-row">
              {sources.slice(0, 4).map((s, i) => (
                <View key={s.id} style={{ marginLeft: i === 0 ? 0 : -7, zIndex: 10 - i }}>
                  <Favicon url={s.url} size={22} ring />
                </View>
              ))}
            </View>
            <Text weight="bold" className="text-[13px]">
              {sources.length} sources
            </Text>
          </Tap>
        ) : null}
        <View className="flex-1" />
        {message.meta?.kind === "report" ? <ActionIcon icon="download-outline" label="Export report" onPress={exportReport} /> : null}
        <ActionIcon icon={speaking ? "stop-circle-outline" : "volume-medium-outline"} label={speaking ? "Stop reading" : "Read aloud"} onPress={speak} active={speaking} />
        <ActionIcon icon="share-outline" label="Share" onPress={share} />
        <ActionIcon icon={saved ? "bookmark" : "bookmark-outline"} label={saved ? "Unsave" : "Save"} onPress={() => toggleSaved(message.id)} active={saved} />
        <ActionIcon icon="refresh" label="Regenerate" onPress={() => !busy && regenerate(message.id)} />
        <ActionIcon icon="copy-outline" label="Copy" onPress={copy} />
      </View>
      {message.meta ? (
        <View className="flex-row items-center gap-1.5 pl-1">
          {level ? <Icon name="bulb-outline" size={12} color={colors.textFaint} /> : null}
          <Text className="text-xs text-ink-faint">
            {[
              model?.name,
              level ? `${level.charAt(0).toUpperCase()}${level.slice(1)} thinking${message.meta.levelRequested === "auto" ? " (auto)" : ""}` : null,
              message.meta.reasoningTokens > 0 ? `${tokens(message.meta.reasoningTokens)} reasoning tokens` : null,
            ]
              .filter(Boolean)
              .join(", ")}
          </Text>
        </View>
      ) : null}

      <Sheet open={open} onClose={() => setOpen(false)} title={`${sources.length} sources`} subtitle="Merged across web search, Atlas fetches and sub-agents. Every citation was matched to one of these.">
        <View className="gap-1">
          {sources.map((s, i) => (
            <Tap
              key={s.id}
              accessibilityRole="link"
              onPress={() => void Linking.openURL(s.url)}
              className="flex-row gap-3 rounded-2xl px-1 py-3"
            >
              <Text weight="bold" className="w-5 pt-0.5 text-right text-xs text-ink-faint">
                {i + 1}
              </Text>
              <Favicon url={s.url} size={26} />
              <View className="flex-1">
                <Text weight="bold" className="text-[15px] leading-5" numberOfLines={2}>
                  {s.title}
                </Text>
                <Text muted className="mt-0.5 text-[13px] leading-[18px]" numberOfLines={2}>
                  {s.snippet}
                </Text>
                <Text className="mt-1 text-xs text-ink-faint">
                  {domainOf(s.url)}, {originLabel[s.origin].toLowerCase()}
                </Text>
              </View>
            </Tap>
          ))}
        </View>
      </Sheet>
    </View>
  );
}

