function useKeyboardVisible() {
  const [visible, setVisible] = useState(false);
  useEffect(() => {
    const show = Keyboard.addListener(Platform.OS === "ios" ? "keyboardWillShow" : "keyboardDidShow", () => setVisible(true));
    const hide = Keyboard.addListener(Platform.OS === "ios" ? "keyboardWillHide" : "keyboardDidHide", () => setVisible(false));
    return () => {
      show.remove();
      hide.remove();
    };
  }, []);
  return visible;
}

export default function ChatScreen() {
  const insets = useSafeAreaInsets();
  const threadId = useApp((s) => s.activeThreadId);
  const messages = useApp((s) => (s.activeThreadId ? s.messages[s.activeThreadId] : undefined));
  const keyboard = useKeyboardVisible();
  const [composerH, setComposerH] = useState(110);
  const scroller = useRef<ScrollView>(null);
  const stick = useRef(true);
  const count = messages?.length ?? 0;

  const bottom = keyboard ? 8 : TAB_BAR_CLEARANCE + insets.bottom;

  useEffect(() => {
    stick.current = true;
    requestAnimationFrame(() => scroller.current?.scrollToEnd({ animated: false }));
  }, [threadId]);

  useEffect(() => {
    if (count > 0) {
      stick.current = true;
      scroller.current?.scrollToEnd({ animated: true });
    }
  }, [count]);

  return (
    <View className="flex-1 bg-background">
      <ScrollView
        ref={scroller}
        keyboardShouldPersistTaps="handled"
        keyboardDismissMode="interactive"
        onScroll={(e) => {
          const { contentOffset, contentSize, layoutMeasurement } = e.nativeEvent;
          stick.current = contentSize.height - contentOffset.y - layoutMeasurement.height < 140;
        }}
        scrollEventThrottle={32}
        onContentSizeChange={() => {
          if (stick.current) scroller.current?.scrollToEnd({ animated: false });
        }}
        contentContainerStyle={{
          flexGrow: 1,
          width: "100%",
          maxWidth: 720,
          alignSelf: "center",
          paddingTop: insets.top + 68,
          paddingBottom: composerH + bottom + 28,
          paddingHorizontal: 18,
          gap: 22,
        }}
      >
        {messages && messages.length > 0 ? (
          messages.map((m, i) =>
            m.role === "user" ? <UserMessage key={m.id} message={m} /> : <AssistantMessage key={m.id} message={m} last={i === messages.length - 1} />,
          )
        ) : (
          <EmptyState />
        )}
      </ScrollView>

      <ChatHeader />

      <KeyboardAvoidingView
        behavior={Platform.OS === "ios" ? "padding" : undefined}
        pointerEvents="box-none"
        style={{ position: "absolute", left: 0, right: 0, bottom: 0 }}
      >
        <View style={{ paddingBottom: bottom, width: "100%", maxWidth: 720, alignSelf: "center" }} pointerEvents="box-none">
          <Composer onLayout={(e) => setComposerH(e.nativeEvent.layout.height)} />
        </View>
      </KeyboardAvoidingView>
    </View>
  );
}

