import { Spinner } from "heroui-native";
import { useEffect, useState } from "react";
import { TextInput, View } from "react-native";
import { Icon } from "@/components/ui/Icon";
import { Sheet } from "@/components/ui/Sheet";
import { Tap } from "@/components/ui/Tap";
import { Text } from "@/components/ui/Text";
import { ActionButton, Pill } from "@/genui/kit";
import { modelRef } from "@/lib/mock/models";
import { useApp } from "@/lib/store";
import { colors, fonts } from "@/lib/theme";
import type { CapabilityProfile, Model, Provider } from "@/lib/types";

const field = {
  fontFamily: fonts.body,
  fontSize: 16,
  color: colors.text,
  backgroundColor: colors.raised,
  borderRadius: 14,
  paddingHorizontal: 14,
  paddingVertical: 11,
} as const;

function Field({ label, hint, children }: { label: string; hint?: string; children: React.ReactNode }) {
  return (
    <View className="gap-1.5">
      <Text weight="medium" muted className="text-[13px]">
        {label}
      </Text>
      {children}
      {hint ? <Text className="text-xs leading-4 text-ink-faint">{hint}</Text> : null}
    </View>
  );
}

const featureLabels: { key: keyof CapabilityProfile["features"]; label: string }[] = [
  { key: "vision", label: "Vision" },
  { key: "tools", label: "Tool calls" },
  { key: "streaming", label: "Streaming" },
  { key: "reasoningText", label: "Reasoning text" },
  { key: "webSearch", label: "Web search" },
  { key: "audio", label: "Audio" },
];

/** Capability profile viewer with probes and manual overrides (PRD §3.5). */
function ModelProfile({ model }: { model: Model }) {
  const overrideProfile = useApp((s) => s.overrideProfile);
  const cap = useApp((s) => s.settings.probeSpendCapUsd);
  const showToast = useApp((s) => s.showToast);
  const [probing, setProbing] = useState<"idle" | "confirm" | "running">("idle");
  const p = model.profile;
  const ref = modelRef(model);

  const runProbes = () => {
    setProbing("running");
    setTimeout(() => {
      overrideProfile(ref, {
        source: p.source === "manual" ? "manual" : "probe",
        confidence: Math.min(0.98, p.confidence + 0.12),
      });
      setProbing("idle");
      showToast(`${model.name} profile updated`);
    }, 1600);
  };

  return (
    <View className="gap-3 pb-1 pt-2">
      <View className="gap-1.5">
        <Text muted className="text-xs">
          Reasoning
        </Text>
        {p.reasoning.style === "none" ? (
          <Text className="text-sm">Not supported. The Thinking control is hidden for this model.</Text>
        ) : (
          <>
            <Text className="text-sm">
              {p.reasoning.style === "effort" ? "Effort levels" : p.reasoning.style === "budget" ? "Token budget" : "On or off"} via{" "}
              <Text weight="bold" className="text-sm">
                {p.reasoning.field}
              </Text>
            </Text>
            <View className="flex-row flex-wrap gap-1">
              {p.reasoning.levels.map((l) => (
                <Pill
                  key={l}
                  label={p.reasoning.budgets?.[l] ? `${l} ${(p.reasoning.budgets[l] / 1024).toFixed(0)}k` : l}
                  tone={l === p.reasoning.defaultLevel ? "primary" : "neutral"}
                />
              ))}
            </View>
          </>
        )}
      </View>

      <View className="gap-1.5">
        <Text muted className="text-xs">
          Features (tap to override)
        </Text>
        <View className="flex-row flex-wrap gap-1.5">
          {featureLabels.map((f) => {
            const on = p.features[f.key];
            return (
              <Tap
                key={f.key}
                accessibilityRole="switch"
                accessibilityState={{ checked: on }}
                onPress={() => overrideProfile(ref, { features: { ...p.features, [f.key]: !on }, source: "manual", confidence: 1 })}
                className={`flex-row items-center gap-1 rounded-full px-2.5 py-1 ${on ? "bg-[rgba(23,201,100,0.12)]" : "bg-raised"}`}
              >
                <Icon name={on ? "checkmark" : "close"} size={12} color={on ? colors.success : colors.textFaint} />
                <Text weight="medium" className="text-xs" style={{ color: on ? colors.success : colors.textMuted }}>
                  {f.label}
                </Text>
              </Tap>
            );
          })}
        </View>
      </View>

      <View className="flex-row items-center gap-3">
        <View className="flex-1 gap-1">
          <View className="h-1.5 overflow-hidden rounded-full bg-raised">
            <View
              className="h-full rounded-full"
              style={{ width: `${p.confidence * 100}%`, backgroundColor: p.confidence >= 0.85 ? colors.success : p.confidence >= 0.5 ? colors.warning : colors.danger }}
            />
          </View>
          <Text className="text-xs text-ink-faint">
            {Math.round(p.confidence * 100)}% confidence, from {p.source}, checked {new Date(p.lastVerified).toLocaleDateString("en-US", { month: "short", day: "numeric" })}, v{p.version}
          </Text>
        </View>
        {probing === "running" ? (
          <Spinner size="sm" />
        ) : (
          <ActionButton size="sm" variant="secondary" label="Run probes" onPress={() => setProbing("confirm")} />
        )}
      </View>

      {probing === "confirm" ? (
        <View className="gap-2 rounded-2xl bg-raised p-3">
          <Text className="text-[13px] leading-[18px]">
            Sends up to 4 tiny requests (max_tokens 16) with no personal data. About $0.002, within your ${cap.toFixed(2)} cap.
            {p.source === "manual" ? " Your manual overrides stay as they are." : ""}
          </Text>
          <View className="flex-row justify-end gap-2">
            <ActionButton size="sm" variant="ghost" label="Cancel" onPress={() => setProbing("idle")} />
            <ActionButton size="sm" label="Run" onPress={runProbes} />
          </View>
        </View>
      ) : null}
    </View>
  );
}

export function ProviderSheet({ open, onClose, providerId }: { open: boolean; onClose: () => void; providerId: string | null }) {
  const providers = useApp((s) => s.providers);
  const models = useApp((s) => s.models);
  const upsertProvider = useApp((s) => s.upsertProvider);
  const removeProvider = useApp((s) => s.removeProvider);
  const addModels = useApp((s) => s.addModels);
  const showToast = useApp((s) => s.showToast);
  const existing = providers.find((p) => p.providerId === providerId);

  const [form, setForm] = useState<Provider>(existing ?? { providerId: "", label: "", baseUrl: "", keyHint: "", headers: [], status: "checking" });
  const [apiKey, setApiKey] = useState("");
  const [fetching, setFetching] = useState(false);
  const [expanded, setExpanded] = useState<string | null>(null);

  useEffect(() => {
    if (open) {
      setForm(existing ?? { providerId: "", label: "", baseUrl: "", keyHint: "", headers: [], status: "checking" });
      setApiKey("");
      setExpanded(null);
    }
  }, [open, existing]);

  const list = models.filter((m) => m.providerId === form.providerId && form.providerId);
  const valid = /^[a-z0-9-]+$/.test(form.providerId) && /^https?:\/\/.+/.test(form.baseUrl);

  const fetchModels = () => {
    if (!valid) return;
    setFetching(true);
    setTimeout(() => {
      if (list.length === 0) {
        const id = `${form.providerId}-chat`;
        addModels([
          {
            id,
            name: `${form.label || form.providerId} chat`,
            providerId: form.providerId,
            contextWindow: 128_000,
            profile: {
              reasoning: { style: "none", levels: [], defaultLevel: "off" },
              features: { vision: false, tools: true, streaming: true, reasoningText: false, audio: false, webSearch: false },
              confidence: 0.45,
              source: "registry",
              lastVerified: Date.now(),
              version: 1,
            },
          },
        ]);
      }
      setFetching(false);
      showToast(`GET ${form.baseUrl.replace(/\/$/, "")}/models: ${Math.max(1, list.length)} models`);
    }, 1100);
  };

  const save = () => {
    upsertProvider({ ...form, label: form.label || form.providerId, keyHint: apiKey ? `…${apiKey.slice(-4)}` : form.keyHint || "none", status: "connected" });
    showToast(existing ? "Provider saved" : "Provider added");
    onClose();
  };

  return (
    <Sheet
      open={open}
      onClose={onClose}
      title={existing ? existing.label : "Add provider"}
      subtitle="Any OpenAI-compatible endpoint. Calls are proxied through the server, never sent from the phone."
      footer={
        <View className="flex-row gap-2">
          {existing ? (
            <View className="flex-1">
              <ActionButton
                variant="danger-soft"
                label="Remove"
                onPress={() => {
                  removeProvider(existing.providerId);
                  showToast("Provider removed");
                  onClose();
                }}
              />
            </View>
          ) : null}
          <View className="flex-1">
            <ActionButton label="Save" disabled={!valid} onPress={save} />
          </View>
        </View>
      }
    >
      <View className="gap-4">
        <Field label="Provider ID" hint="Lowercase letters, numbers and dashes.">
          <TextInput
            editable={!existing}
            value={form.providerId}
            onChangeText={(providerId) => setForm({ ...form, providerId: providerId.toLowerCase() })}
            placeholder="together"
            placeholderTextColor={colors.textFaint}
            autoCapitalize="none"
            accessibilityLabel="Provider ID"
            style={[field, !existing ? null : { opacity: 0.6 }]}
          />
        </Field>
        <Field label="Name">
          <TextInput value={form.label} onChangeText={(label) => setForm({ ...form, label })} placeholder="Together AI" placeholderTextColor={colors.textFaint} accessibilityLabel="Name" style={field} />
        </Field>
        <Field label="Base URL">
          <TextInput
            value={form.baseUrl}
            onChangeText={(baseUrl) => setForm({ ...form, baseUrl })}
            placeholder="https://api.together.xyz/v1"
            placeholderTextColor={colors.textFaint}
            autoCapitalize="none"
            keyboardType="url"
            accessibilityLabel="Base URL"
            style={field}
          />
        </Field>
        <Field label="API key" hint="Encrypted at rest on the server and never sent back to this device.">
          <TextInput
            value={apiKey}
            onChangeText={setApiKey}
            placeholder={form.keyHint && form.keyHint !== "none" ? `Saved key ${form.keyHint}` : "sk-…"}
            placeholderTextColor={colors.textFaint}
            secureTextEntry
            autoCapitalize="none"
            accessibilityLabel="API key"
            style={field}
          />
        </Field>
        <Field label="Extra headers">
          <View className="gap-2">
            {form.headers.map((h, i) => (
              <View key={i} className="flex-row items-center gap-2">
                <TextInput
                  value={h.key}
                  onChangeText={(key) => setForm({ ...form, headers: form.headers.map((x, j) => (j === i ? { ...x, key } : x)) })}
                  placeholder="Header"
                  placeholderTextColor={colors.textFaint}
                  autoCapitalize="none"
                  accessibilityLabel="Header name"
                  style={[field, { flex: 1 }]}
                />
                <TextInput
                  value={h.value}
                  onChangeText={(value) => setForm({ ...form, headers: form.headers.map((x, j) => (j === i ? { ...x, value } : x)) })}
                  placeholder="Value"
                  placeholderTextColor={colors.textFaint}
                  autoCapitalize="none"
                  accessibilityLabel="Header value"
                  style={[field, { flex: 1.4 }]}
                />
                <Tap accessibilityLabel="Remove header" onPress={() => setForm({ ...form, headers: form.headers.filter((_, j) => j !== i) })}>
                  <Icon name="remove-circle" size={22} color={colors.textFaint} />
                </Tap>
              </View>
            ))}
            <Tap onPress={() => setForm({ ...form, headers: [...form.headers, { key: "", value: "" }] })} className="flex-row items-center gap-1.5 self-start py-1">
              <Icon name="add-circle" size={18} color={colors.primary} />
              <Text weight="medium" className="text-sm text-primary">
                Add header
              </Text>
            </Tap>
          </View>
        </Field>

        <View className="gap-2">
          <View className="flex-row items-center justify-between">
            <Text weight="bold" className="text-base">
              Models
            </Text>
            {fetching ? <Spinner size="sm" /> : <ActionButton size="sm" variant="secondary" icon="refresh" label="Fetch models" disabled={!valid} onPress={fetchModels} />}
          </View>
          {list.length === 0 ? (
            <Text muted className="text-[13px]">
              No models yet. Fetch them from the endpoint's /models list.
            </Text>
          ) : (
            <View className="overflow-hidden rounded-3xl bg-card">
              {list.map((m, i) => {
                const ref = modelRef(m);
                const isOpen = expanded === ref;
                return (
                  <View key={ref} className={`px-4 py-3 ${i < list.length - 1 ? "border-b border-hairline" : ""}`}>
                    <Tap accessibilityRole="button" accessibilityState={{ expanded: isOpen }} onPress={() => setExpanded(isOpen ? null : ref)} className="flex-row items-center gap-2">
                      <Text weight="bold" className="flex-1 text-[15px]">
                        {m.name}
                      </Text>
                      {m.profile.source === "manual" ? <Pill label="Manual" tone="primary" /> : null}
                      {m.profile.confidence < 0.8 ? <Pill label="Unverified" tone="warning" /> : null}
                      <Icon name={isOpen ? "chevron-up" : "chevron-down"} size={16} color={colors.textFaint} />
                    </Tap>
                    {isOpen ? <ModelProfile model={m} /> : null}
                  </View>
                );
              })}
            </View>
          )}
        </View>
      </View>
    </Sheet>
  );
}

import { Switch } from "heroui-native";
import { useState, type ReactNode } from "react";
import { ScrollView, TextInput, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { ModelPicker } from "@/components/chat/ModelPicker";
import { TAB_BAR_CLEARANCE } from "@/components/navigation/AppTabs";
import { ProviderSheet } from "@/components/settings/ProviderSheet";
import { Icon, type IconName } from "@/components/ui/Icon";
import { Group, ScreenHeader } from "@/components/ui/ScreenHeader";
import { Segmented } from "@/components/ui/Segmented";
import { Tap } from "@/components/ui/Tap";
import { Text } from "@/components/ui/Text";
import { findModel, useApp } from "@/lib/store";
import { colors, fonts } from "@/lib/theme";

function Row({
  icon,
  label,
  detail,
  value,
  onPress,
  right,
  last,
}: {
  icon?: IconName;
  label: string;
  detail?: string;
  value?: string;
  onPress?: () => void;
  right?: ReactNode;
  last?: boolean;
}) {
  const body = (
    <View className={`flex-row items-center gap-3 px-4 py-3.5 ${last ? "" : "border-b border-hairline"}`}>
      {icon ? <Icon name={icon} size={19} color={colors.textMuted} /> : null}
      <View className="flex-1">
        <Text weight="medium" className="text-base">
          {label}
        </Text>
        {detail ? (
          <Text muted className="text-[13px] leading-[18px]" numberOfLines={2}>
            {detail}
          </Text>
        ) : null}
      </View>
      {value ? (
        <Text muted className="max-w-[45%] text-[15px]" numberOfLines={1}>
          {value}
        </Text>
      ) : null}
      {right}
      {onPress ? <Icon name="chevron-forward" size={16} color={colors.textFaint} /> : null}
    </View>
  );
  return onPress ? (
    <Tap accessibilityRole="button" onPress={onPress}>
      {body}
    </Tap>
  ) : (
    body
  );
}

function Stack({ label, children, last }: { label: string; children: ReactNode; last?: boolean }) {
  return (
    <View className={`gap-2 px-4 py-3.5 ${last ? "" : "border-b border-hairline"}`}>
      <Text weight="medium" className="text-base">
        {label}
      </Text>
      {children}
    </View>
  );
}

export default function SettingsScreen() {
  const insets = useSafeAreaInsets();
  const providers = useApp((s) => s.providers);
  const models = useApp((s) => s.models);
  const settings = useApp((s) => s.settings);
  const update = useApp((s) => s.updateSettings);
  const [providerSheet, setProviderSheet] = useState<{ id: string | null } | null>(null);
  const [picker, setPicker] = useState<"default" | "research" | null>(null);
  const [instructions, setInstructions] = useState(settings.customInstructions);

  return (
    <View className="flex-1 bg-background">
      <ScrollView
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={{
          paddingTop: insets.top + 16,
          paddingBottom: TAB_BAR_CLEARANCE + insets.bottom + 24,
          paddingHorizontal: 16,
          width: "100%",
          maxWidth: 720,
          alignSelf: "center",
        }}
      >
        <ScreenHeader title="Settings" />

        <Group label="Providers" footer="Bring your own OpenAI-compatible endpoints. Keys stay on the server.">
          {providers.map((p) => {
            const n = models.filter((m) => m.providerId === p.providerId).length;
            return (
              <Row
                key={p.providerId}
                label={p.label}
                detail={`${p.baseUrl.replace(/^https?:\/\//, "")}, ${n} ${n === 1 ? "model" : "models"}`}
                right={<View className={`h-2 w-2 rounded-full ${p.status === "connected" ? "bg-success" : "bg-danger"}`} />}
                onPress={() => setProviderSheet({ id: p.providerId })}
              />
            );
          })}
          <Tap accessibilityRole="button" onPress={() => setProviderSheet({ id: null })} className="flex-row items-center gap-3 px-4 py-3.5">
            <Icon name="add-circle" size={19} color={colors.primary} />
            <Text weight="medium" className="text-base text-primary">
              Add provider
            </Text>
          </Tap>
        </Group>

        <Group label="Models">
          <Row icon="cube-outline" label="Default model" value={findModel(models, settings.defaultModelRef).name} onPress={() => setPicker("default")} />
          <Row
            icon="telescope-outline"
            label="Research model"
            detail="Writes the final report in Deep Research"
            value={settings.researchModelRef ? findModel(models, settings.researchModelRef).name : "Same as chat"}
            onPress={() => setPicker("research")}
            last
          />
        </Group>

        <Group label="Custom instructions" footer="Added to every conversation, separate from memory.">
          <View className="p-3">
            <TextInput
              value={instructions}
              onChangeText={setInstructions}
              onBlur={() => update({ customInstructions: instructions })}
              multiline
              maxLength={1500}
              placeholder="How should Atlas respond? What should it know about you?"
              placeholderTextColor={colors.textFaint}
              accessibilityLabel="Custom instructions"
              style={{ fontFamily: fonts.body, fontSize: 16, lineHeight: 22, color: colors.text, minHeight: 96, padding: 6, textAlignVertical: "top", outlineStyle: "none" } as object}
            />
            <Text className="px-1.5 text-right text-xs text-ink-faint">{instructions.length} / 1500</Text>
          </View>
        </Group>

        <Group label="Agents and web" footer="Asking for sub-agents in a message always overrides the setting.">
          <Stack label="Sub-agents">
            <Segmented
              accessibilityLabel="Sub-agents"
              value={settings.subagentMode}
              onChange={(subagentMode) => update({ subagentMode })}
              options={[
                { value: "off", label: "Off" },
                { value: "auto", label: "Auto" },
                { value: "offer", label: "Always offer" },
              ]}
            />
          </Stack>
          <Stack label="Web access">
            <Segmented
              accessibilityLabel="Web access"
              value={settings.webMode}
              onChange={(webMode) => update({ webMode })}
              options={[
                { value: "auto", label: "Auto" },
                { value: "native", label: "Native only" },
                { value: "app", label: "App tools" },
              ]}
            />
            <Text muted className="text-[13px] leading-[18px]">
              {settings.webMode === "auto"
                ? "Uses the model's own web search when it has one, otherwise Atlas fetches pages itself."
                : settings.webMode === "native"
                  ? "Only the model's built-in search. Costs go to your key; models without it can't browse."
                  : "Atlas always fetches pages itself, even when the model could search."}
            </Text>
          </Stack>
          <Stack label="Search fallback" last>
            <Segmented
              accessibilityLabel="Search fallback"
              value={settings.searchProvider}
              onChange={(searchProvider) => update({ searchProvider })}
              options={[
                { value: "none", label: "Free only" },
                { value: "brave", label: "Brave" },
                { value: "tavily", label: "Tavily" },
                { value: "searxng", label: "SearXNG" },
              ]}
            />
            {settings.searchProvider !== "none" ? (
              <TextInput
                value={settings.searchKeyHint}
                onChangeText={(searchKeyHint) => update({ searchKeyHint })}
                placeholder={settings.searchProvider === "searxng" ? "https://searx.example.org" : "API key"}
                placeholderTextColor={colors.textFaint}
                secureTextEntry={settings.searchProvider !== "searxng"}
                autoCapitalize="none"
                accessibilityLabel="Search provider key or URL"
                style={{ fontFamily: fonts.body, fontSize: 15, color: colors.text, backgroundColor: colors.raised, borderRadius: 14, paddingHorizontal: 14, paddingVertical: 10 }}
              />
            ) : (
              <Text muted className="text-[13px]">
                Wikipedia and Hacker News only.
              </Text>
            )}
          </Stack>
        </Group>

        <Group label="Voice">
          <Stack label="Speech to text">
            <Segmented
              accessibilityLabel="Speech to text"
              value={settings.voiceInput}
              onChange={(voiceInput) => update({ voiceInput })}
              options={[
                { value: "device", label: "On device" },
                { value: "endpoint", label: "My endpoint" },
              ]}
            />
          </Stack>
          <Stack label="Text to speech">
            <Segmented
              accessibilityLabel="Text to speech"
              value={settings.voiceOutput}
              onChange={(voiceOutput) => update({ voiceOutput })}
              options={[
                { value: "device", label: "Device voice" },
                { value: "endpoint", label: "My endpoint" },
              ]}
            />
          </Stack>
          <Row
            label="Read replies aloud"
            detail="Components are summarised in a sentence."
            right={<Switch isSelected={settings.readRepliesAloud} onSelectedChange={(readRepliesAloud) => update({ readRepliesAloud })} />}
            last
          />
        </Group>

        <Group label="Capability probes" footer="Probes are tiny requests that learn what each endpoint supports. They never contain your messages.">
          <Stack label="Spend cap per model" last>
            <Segmented
              accessibilityLabel="Probe spend cap"
              value={String(settings.probeSpendCapUsd) as "0.01" | "0.05" | "0.25"}
              onChange={(v) => update({ probeSpendCapUsd: Number(v) })}
              options={[
                { value: "0.01", label: "$0.01" },
                { value: "0.05", label: "$0.05" },
                { value: "0.25", label: "$0.25" },
              ]}
            />
          </Stack>
        </Group>

        <Group label="About">
          <Row label="Version" value="0.1.0" />
          <Row label="Data" value="Mock, no backend" />
          <Row label="Decisions" value="Heuristic (Jev later)" last />
        </Group>
      </ScrollView>

      <ProviderSheet open={providerSheet !== null} onClose={() => setProviderSheet(null)} providerId={providerSheet?.id ?? null} />
      <ModelPicker
        open={picker !== null}
        onClose={() => setPicker(null)}
        title={picker === "research" ? "Research model" : "Default model"}
        value={picker === "research" ? (settings.researchModelRef ?? settings.defaultModelRef) : settings.defaultModelRef}
        onSelect={(ref) => update(picker === "research" ? { researchModelRef: ref } : { defaultModelRef: ref })}
      />
    </View>
  );
}

