const [responder] = useState(() => {
  const update = (x: number) => {
    const l = latest.current;
    const v = snap(x, l.width, l.min, l.max, l.step);
    if (v !== l.value) l.onChange(v);
  };
  return PanResponder.create({
    onStartShouldSetPanResponder: () => true,
    onMoveShouldSetPanResponderCapture: (_e, g) => Math.abs(g.dx) > Math.abs(g.dy),
    onPanResponderTerminationRequest: () => false,
    onPanResponderGrant: (e) => {
      startX.current = e.nativeEvent.locationX;
      update(startX.current);
    },
    onPanResponderMove: (_e, g) => update(startX.current + g.dx),
  });
});

const HANDLE = 28;

function snap(x: number, width: number, min: number, max: number, step: number): number {
  const w = Math.max(1, width - HANDLE);
  const ratio = Math.min(1, Math.max(0, (x - HANDLE / 2) / w));
  const raw = min + ratio * (max - min);
  return Math.min(max, Math.max(min, Math.round(raw / step) * step));
}

