                  onPress={() => open(t.id)}
                  onLongPress={() => setMenuFor(t)}
                  className={`flex-row items-center gap-3 px-4 py-3.5 ${i < g.items.length - 1 ? "border-b border-hairline" : ""}`}
                >
                  <Icon
