          showsHorizontalScrollIndicator={false}
          className="-mx-4 mb-4"
          contentContainerStyle={{ paddingHorizontal: 16, gap: 8 }}
        >
          {[
            { value: "all" as const, label: "All", icon: "albums-outline" as IconName },
            ...categories,
          ].map((c) => {
            const on = filter === c.value;
            const n =
              c.value === "all"
                ? memories.length
                : memories.filter((m) => m.category === c.value).length;
            return (
              <Tap
                key={c.value}
                haptic
                accessibilityRole="button"
                accessibilityState={{ selected: on }}
                onPress={() => setFilter(c.value)}
                className={`flex-row items-center gap-1.5 rounded-full px-3.5 py-2 ${on ? "bg-primary-soft" : "bg-raised"}`}
              >
                <Text
                  weight={on ? "bold" : "medium"}
                  className={`text-sm ${on ? "text-primary-strong" : ""}`}
                >
                  {c.label}
                </Text>
                <Text className={`text-xs ${on ? "text-primary-strong" : "text-ink-faint"}`}>
                  {n}
                </Text>
              </Tap>
            );
          })}
        </ScrollView>

        {shown.length === 0 ? (
          <View className="items-center gap-3 py-12">
            <Text muted className="text-center text-[15px]">
              Nothing here yet. Tell Atlas something like “Remember that I’m vegetarian”, or add one
              yourself.
            </Text>
            <ActionButton
              size="sm"
              variant="secondary"
              icon="add"
              label="Add memory"
              onPress={() =>
                setDraft({
                  text: "",
                  category: filter === "all" ? "preference" : filter,
                  scope: "global",
                })
              }
            />
          </View>
        ) : (
          <Group>
            {shown.map((m, i) => {
              const cat = categories.find((c) => c.value === m.category)!;
              return (
                <Tap
                  key={m.id}
                  accessibilityRole="button"
                  accessibilityHint="Edit memory"
                  onPress={() =>
                    setDraft({ id: m.id, text: m.text, category: m.category, scope: m.scope })
                  }
                  className={`flex-row items-start gap-3 px-4 py-3.5 ${i < shown.length - 1 ? "border-b border-hairline" : ""}`}
                >
                  <View className="pt-0.5">
                    <Icon name={cat.icon} size={18} color={colors.textMuted} />
                  </View>
                  <View className="flex-1">
                    <Text weight="medium" className="text-base leading-[22px]">
                      {m.text}
                    </Text>
                    <Text className="mt-0.5 text-xs text-ink-faint">
                      {m.scope === "global" ? "All chats" : "One chat"},{" "}
                      {Math.round(m.confidence * 100)}% confidence,{" "}
                      {new Date(m.createdAt).toLocaleDateString("en-US", {
                        month: "short",
                        day: "numeric",
                      })}
                    </Text>
                  </View>
                  <Icon name="chevron-forward" size={16} color={colors.textFaint} />
                </Tap>
              );
            })}
          </Group>
        )}
      </ScrollView>

      <Sheet
        open={draft !== null}
        onClose={() => setDraft(null)}
        title={draft?.id ? "Edit memory" : "New memory"}
        footer={
          <View className="flex-row gap-2">
            {draft?.id ? (
              <View className="flex-1">
                <ActionButton
                  variant="danger-soft"
                  icon="trash-outline"
                  label="Delete"
                  onPress={() => {
                    if (draft.id) deleteMemory(draft.id);
                    setDraft(null);
                    showToast("Memory deleted");
                  }}
                />
              </View>
            ) : null}
            <View className="flex-1">
              <ActionButton label="Save" disabled={!draft?.text.trim()} onPress={save} />
            </View>
          </View>
        }
      >
        {draft ? (
          <View className="gap-4">
            <TextInput
              value={draft.text}
              onChangeText={(text) => setDraft({ ...draft, text })}
              multiline
              autoFocus={!draft.id}
              placeholder="Prefers window seats on flights"
              placeholderTextColor={colors.textFaint}
              accessibilityLabel="Memory text"
              style={{
                fontFamily: fonts.body,
                fontSize: 16,
                lineHeight: 22,
                color: colors.text,
                backgroundColor: colors.raised,
                borderRadius: 18,
                padding: 14,
                minHeight: 88,
                textAlignVertical: "top",
              }}
            />
            <View className="gap-2">
              <Text weight="medium" muted className="text-[13px]">
                Category
              </Text>
              <View className="flex-row flex-wrap gap-2">
                {categories.map((c) => {
                  const on = draft.category === c.value;
                  return (
                    <Tap
                      key={c.value}
                      accessibilityRole="radio"
                      accessibilityState={{ selected: on }}
                      onPress={() => setDraft({ ...draft, category: c.value })}
                      className={`flex-row items-center gap-1.5 rounded-full px-3 py-2 ${on ? "bg-primary-soft" : "bg-raised"}`}
                    >
                      <Icon
                        name={c.icon}
                        size={14}
                        color={on ? colors.primaryStrong : colors.textMuted}
                      />
                      <Text
                        weight={on ? "bold" : "medium"}
                        className={`text-sm ${on ? "text-primary-strong" : ""}`}
                      >
                        {c.label}
                      </Text>
                    </Tap>
                  );
                })}
              </View>
            </View>
            <View className="gap-2">
              <Text weight="medium" muted className="text-[13px]">
                Applies to
              </Text>
              <Segmented
                accessibilityLabel="Memory scope"
                value={draft.scope}
                onChange={(scope) => setDraft({ ...draft, scope })}
                options={[
                  { value: "global", label: "All chats" },
                  { value: "thread", label: "One chat" },
                ]}
              />
            </View>
          </View>
        ) : null}
      </Sheet>
    </View>
  );
}

import { Switch } from "heroui-native";
import { useState, type ReactNode } from "react";
import { ScrollView, TextInput, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { ModelPicker } from "@/components/chat/ModelPicker";
import { TAB_BAR_CLEARANCE } from "@/components/navigation/AppTabs";
import { ProviderSheet } from "@/components/settings/ProviderSheet";
import { Icon, type IconName } from "@/components/ui/Icon";
import { Group, ScreenHeader } from "@/components/ui/ScreenHeader";
import { Segmented } from "@/components/ui/Segmented";
import { Tap } from "@/components/ui/Tap";
import { Text } from "@/components/ui/Text";
import { findModel, useApp } from "@/lib/store";
import { colors, fonts } from "@/lib/theme";

function Row({
  icon,
  label,
  detail,
  value,
  onPress,
  right,
  last,
}: {
  icon?: IconName;
  label: string;
  detail?: string;
  value?: string;
  onPress?: () => void;
  right?: ReactNode;
  last?: boolean;
}) {
  const body = (
    <View
      className={`flex-row items-center gap-3 px-4 py-3.5 ${last ? "" : "border-b border-hairline"}`}
    >
      {icon ? <Icon name={icon} size={19} color={colors.textMuted} /> : null}
      <View className="flex-1">
        <Text weight="medium" className="text-base">
          {label}
        </Text>
        {detail ? (
          <Text muted className="text-[13px] leading-[18px]" numberOfLines={2}>
            {detail}
          </Text>
        ) : null}
      </View>
      {value ? (
        <Text muted className="max-w-[42%] text-[15px]" numberOfLines={1}>
          {value}
        </Text>
      ) : null}
      {right}
      {onPress ? <Icon name="chevron-forward" size={16} color={colors.textFaint} /> : null}
    </View>
  );
  return onPress ? (
    <Tap accessibilityRole="button" onPress={onPress}>
      {body}
    </Tap>
  ) : (
    body
  );
}

function Stack({ label, children, last }: { label: string; children: ReactNode; last?: boolean }) {
  return (
    <View className={`gap-2 px-4 py-3.5 ${last ? "" : "border-b border-hairline"}`}>
      <Text weight="medium" className="text-base">
        {label}
      </Text>
      {children}
    </View>
  );
}

export default function SettingsScreen() {
  const insets = useSafeAreaInsets();
  const providers = useApp((s) => s.providers);
  const models = useApp((s) => s.models);
  const settings = useApp((s) => s.settings);
  const update = useApp((s) => s.updateSettings);
  const [providerSheet, setProviderSheet] = useState<{ id: string | null } | null>(null);
  const [picker, setPicker] = useState<"default" | "research" | null>(null);
  const [instructions, setInstructions] = useState(settings.customInstructions);

  return (
    <View className="flex-1 bg-background">
      <ScrollView
        keyboardShouldPersistTaps="handled"
        contentContainerStyle={{
          paddingTop: insets.top + 16,
          paddingBottom: TAB_BAR_CLEARANCE + insets.bottom + 24,
          paddingHorizontal: 16,
          width: "100%",
          maxWidth: 720,
          alignSelf: "center",
        }}
      >
        <ScreenHeader title="Settings" />

        <Group
          label="Providers"
          footer="Bring your own OpenAI-compatible endpoints. Keys stay on the server."
        >
          {providers.map((p) => {
            const n = models.filter((m) => m.providerId === p.providerId).length;
            return (
              <Row
                key={p.providerId}
                label={p.label}
                detail={`${p.baseUrl.replace(/^https?:\/\//, "")}, ${n} ${n === 1 ? "model" : "models"}`}
                right={
                  <View
                    className={`h-2 w-2 rounded-full ${p.status === "connected" ? "bg-success" : "bg-danger"}`}
                  />
                }
                onPress={() => setProviderSheet({ id: p.providerId })}
              />
            );
          })}
          <Tap
            accessibilityRole="button"
            onPress={() => setProviderSheet({ id: null })}
            className="flex-row items-center gap-3 px-4 py-3.5"
          >
            <Icon name="add-circle" size={19} color={colors.primary} />
            <Text weight="medium" className="text-base text-primary">
              Add provider
            </Text>
          </Tap>
        </Group>

        <Group label="Models">
          <Row
            label="Default model"
            value={findModel(models, settings.defaultModelRef).name}
            onPress={() => setPicker("default")}
          />
          <Row
            label="Research model"
            detail="Writes the final report in Deep Research"
            value={
              settings.researchModelRef
                ? findModel(models, settings.researchModelRef).name
                : "Same as chat"
            }
            onPress={() => setPicker("research")}
            last
          />
        </Group>

        <Group
          label="Custom instructions"
          footer="Added to every conversation, separate from memory."
        >
          <View className="p-3">
            <TextInput
              value={instructions}
              onChangeText={setInstructions}
              onBlur={() => update({ customInstructions: instructions })}
              multiline
              maxLength={1500}
              placeholder="How should Atlas respond? What should it know about you?"
              placeholderTextColor={colors.textFaint}
              accessibilityLabel="Custom instructions"
              style={
                {
                  fontFamily: fonts.body,
                  fontSize: 16,
                  lineHeight: 22,
                  color: colors.text,
                  minHeight: 96,
                  padding: 6,
                  textAlignVertical: "top",
                  outlineStyle: "none",
                  resize: "none",
                } as object
              }
            />
            <Text className="px-1.5 text-right text-xs text-ink-faint">
              {instructions.length} / 1500
            </Text>
          </View>
        </Group>

        <Group
          label="Agents and web"
          footer="Asking for sub-agents in a message always overrides the setting."
        >
          <Stack label="Sub-agents">
            <Segmented
              accessibilityLabel="Sub-agents"
              value={settings.subagentMode}
              onChange={(subagentMode) => update({ subagentMode })}
              options={[
                { value: "off", label: "Off" },
                { value: "auto", label: "Auto" },
                { value: "offer", label: "Always offer" },
              ]}
            />
          </Stack>
          <Stack label="Web access">
            <Segmented
              accessibilityLabel="Web access"
              value={settings.webMode}
              onChange={(webMode) => update({ webMode })}
              options={[
                { value: "auto", label: "Auto" },
                { value: "native", label: "Native only" },
                { value: "app", label: "App tools" },
              ]}
            />
            <Text muted className="text-[13px] leading-[18px]">
              {settings.webMode === "auto"
                ? "Uses the model's own web search when it has one, otherwise Atlas fetches pages itself."
                : settings.webMode === "native"
                  ? "Only the model's built-in search. Costs go to your key; models without it can't browse."
                  : "Atlas always fetches pages itself, even when the model could search."}
            </Text>
          </Stack>
          <Stack label="Search fallback" last>
            <Segmented
              accessibilityLabel="Search fallback"
              value={settings.searchProvider}
              onChange={(searchProvider) => update({ searchProvider })}
              options={[
                { value: "none", label: "Free only" },
                { value: "brave", label: "Brave" },
                { value: "tavily", label: "Tavily" },
                { value: "searxng", label: "SearXNG" },
              ]}
            />
            {settings.searchProvider !== "none" ? (
              <TextInput
                value={settings.searchKeyHint}
                onChangeText={(searchKeyHint) => update({ searchKeyHint })}
                placeholder={
                  settings.searchProvider === "searxng" ? "https://searx.example.org" : "API key"
                }
                placeholderTextColor={colors.textFaint}
                secureTextEntry={settings.searchProvider !== "searxng"}
                autoCapitalize="none"
                accessibilityLabel="Search provider key or URL"
                style={{
                  fontFamily: fonts.body,
                  fontSize: 15,
                  color: colors.text,
                  backgroundColor: colors.raised,
                  borderRadius: 14,
                  paddingHorizontal: 14,
                  paddingVertical: 10,
                }}
              />
            ) : (
              <Text muted className="text-[13px]">
                Wikipedia and Hacker News only.
              </Text>
            )}
          </Stack>
        </Group>

        <Group label="Voice">
          <Stack label="Speech to text">
            <Segmented
              accessibilityLabel="Speech to text"
              value={settings.voiceInput}
              onChange={(voiceInput) => update({ voiceInput })}
              options={[
                { value: "device", label: "On device" },
                { value: "endpoint", label: "My endpoint" },
              ]}
            />
          </Stack>
          <Stack label="Text to speech">
            <Segmented
              accessibilityLabel="Text to speech"
              value={settings.voiceOutput}
              onChange={(voiceOutput) => update({ voiceOutput })}
              options={[
                { value: "device", label: "Device voice" },
                { value: "endpoint", label: "My endpoint" },
              ]}
            />
          </Stack>
          <Row
            label="Read replies aloud"
            detail="Components are summarised in a sentence."
            right={
              <Switch
                accessibilityLabel="Read replies aloud"
                isSelected={settings.readRepliesAloud}
                onSelectedChange={(readRepliesAloud) => update({ readRepliesAloud })}
              />
            }
            last
          />
        </Group>

        <Group
          label="Capability probes"
          footer="Probes are tiny requests that learn what each endpoint supports. They never contain your messages."
        >
          <Stack label="Spend cap per model" last>
            <Segmented
              accessibilityLabel="Probe spend cap"
              value={String(settings.probeSpendCapUsd) as "0.01" | "0.05" | "0.25"}
              onChange={(v) => update({ probeSpendCapUsd: Number(v) })}
              options={[
                { value: "0.01", label: "$0.01" },
                { value: "0.05", label: "$0.05" },
                { value: "0.25", label: "$0.25" },
              ]}
            />
          </Stack>
        </Group>

        <Group label="About">
          <Row label="Version" value="0.1.0" />
          <Row label="Data" value="Mock, no backend" />
          <Row label="Decisions" value="Heuristic (Jev later)" last />
        </Group>
      </ScrollView>

      <ProviderSheet
        open={providerSheet !== null}
        onClose={() => setProviderSheet(null)}
        providerId={providerSheet?.id ?? null}
      />
      <ModelPicker
        open={picker !== null}
        onClose={() => setPicker(null)}
        title={picker === "research" ? "Research model" : "Default model"}
        value={
          picker === "research"
            ? (settings.researchModelRef ?? settings.defaultModelRef)
            : settings.defaultModelRef
        }
        onSelect={(ref) =>
          update(picker === "research" ? { researchModelRef: ref } : { defaultModelRef: ref })
        }
      />
    </View>
  );
}

