import { createContext, useContext, useEffect, useState, type ReactNode } from "react";
import { BackHandler, Keyboard, Platform, StyleSheet, useWindowDimensions, View } from "react-native";
import { Gesture, GestureDetector } from "react-native-gesture-handler";
import Animated, {
  interpolate,
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSpring,
} from "react-native-reanimated";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { scheduleOnRN } from "react-native-worklets";
import { colors } from "@/lib/theme";

type DrawerApi = { open: () => void; close: () => void; isOpen: boolean };

const DrawerContext = createContext<DrawerApi>({ open: () => {}, close: () => {}, isOpen: false });

export const useDrawer = () => useContext(DrawerContext);

const SPRING = { damping: 30, stiffness: 300, mass: 0.9, overshootClamping: true };
const FLING = 450;

/**
 * Push-style side drawer: the panel sits behind the chat, and the chat slides right as a rounded card.
 * Open from the header button or a swipe from the left edge; close by tapping or swiping the card.
 */
export function SideDrawer({ panel, children }: { panel: ReactNode; children: ReactNode }) {
  const { width } = useWindowDimensions();
  const insets = useSafeAreaInsets();
  const reduced = useReducedMotion();
  const W = Math.min(340, Math.round(width * 0.82));
  const progress = useSharedValue(0);
  const start = useSharedValue(0);
  const [isOpen, setIsOpen] = useState(false);

  const settle = (target: number) => {
    setIsOpen(target === 1);
    if (target === 1) Keyboard.dismiss();
  };

  const animateTo = (target: 0 | 1) => {
    progress.set(reduced ? target : withSpring(target, SPRING));
    settle(target);
  };

  const open = () => animateTo(1);
  const close = () => animateTo(0);

  useEffect(() => {
    if (!isOpen) return;
    if (Platform.OS === "web") {
      const onKey = (e: KeyboardEvent) => {
        if (e.key === "Escape") {
          progress.set(withSpring(0, SPRING));
          setIsOpen(false);
        }
      };
      window.addEventListener("keydown", onKey);
      return () => window.removeEventListener("keydown", onKey);
    }
    const sub = BackHandler.addEventListener("hardwareBackPress", () => {
      progress.set(withSpring(0, SPRING));
      setIsOpen(false);
      return true;
    });
    return () => sub.remove();
  }, [isOpen, progress]);

  /** Horizontal drag that tracks the finger, then springs open or shut on release. */
  const drag = (enabled: boolean, openBias: number) =>
    Gesture.Pan()
      .enabled(enabled)
      .activeOffsetX([-10, 10])
      .failOffsetY([-14, 14])
      .onBegin(() => {
        start.set(progress.get());
      })
      .onUpdate((e) => {
        progress.set(Math.min(1, Math.max(0, start.get() + e.translationX / W)));
      })
      .onEnd((e) => {
        const target =
          e.velocityX > FLING ? 1 : e.velocityX < -FLING ? 0 : progress.get() > openBias ? 1 : 0;
        progress.set(reduced ? target : withSpring(target, SPRING));
        scheduleOnRN(settle, target);
      });

  const edgeGesture = drag(!isOpen, 0.35);
  const panelGesture = drag(isOpen, 0.65);
  const cardGesture = Gesture.Exclusive(
    drag(isOpen, 0.65),
    Gesture.Tap()
      .enabled(isOpen)
      .onEnd(() => {
        progress.set(reduced ? 0 : withSpring(0, SPRING));
        scheduleOnRN(settle, 0);
      })
  );

  const cardStyle = useAnimatedStyle(() => ({
    transform: [{ translateX: progress.get() * W }],
    borderRadius: progress.get() * 34,
    borderColor: `rgba(255, 255, 255, ${0.12 * progress.get()})`,
  }));
  const dimStyle = useAnimatedStyle(() => ({ opacity: progress.get() * 0.5 }));
  const panelStyle = useAnimatedStyle(() => ({
    opacity: interpolate(progress.get(), [0, 1], [0.4, 1]),
    transform: [{ translateX: interpolate(progress.get(), [0, 1], [-W * 0.16, 0]) }],
  }));

  return (
    <DrawerContext.Provider value={{ open, close, isOpen }}>
      <View style={styles.root}>
        <Animated.View
          accessibilityElementsHidden={!isOpen}
          importantForAccessibility={isOpen ? "auto" : "no-hide-descendants"}
          style={[styles.panel, { width: W, pointerEvents: isOpen ? "auto" : "none" }, panelStyle]}
        >
          <GestureDetector gesture={panelGesture}>
            <View style={{ flex: 1 }}>{panel}</View>
          </GestureDetector>
        </Animated.View>

        <Animated.View style={[styles.card, cardStyle]}>
          <View
            style={{ flex: 1 }}
            accessibilityElementsHidden={isOpen}
            importantForAccessibility={isOpen ? "no-hide-descendants" : "auto"}
          >
            {children}
          </View>
          <GestureDetector gesture={cardGesture}>
            <Animated.View
              accessible={isOpen}
              accessibilityRole="button"
              accessibilityLabel="Close menu"
              onAccessibilityTap={close}
              style={[StyleSheet.absoluteFill, styles.dim, { pointerEvents: isOpen ? "auto" : "none" }, dimStyle]}
            />
          </GestureDetector>
          {!isOpen ? (
            <GestureDetector gesture={edgeGesture}>
              <View style={[styles.edge, { top: insets.top + 64 }]} />
            </GestureDetector>
          ) : null}
        </Animated.View>
      </View>
    </DrawerContext.Provider>
  );
}

const styles = StyleSheet.create({
  root: { flex: 1, backgroundColor: colors.drawer, overflow: "hidden" },
  panel: { position: "absolute", top: 0, bottom: 0, left: 0 },
  card: {
    flex: 1,
    overflow: "hidden",
    backgroundColor: colors.background,
    borderWidth: StyleSheet.hairlineWidth,
  },
  dim: { backgroundColor: "#000" },
  edge: { position: "absolute", left: 0, bottom: 0, width: 14 },
});

import { router, type Href } from "expo-router";
import { useMemo } from "react";
import { ScrollView, View } from "react-native";
import { useSafeAreaInsets } from "react-native-safe-area-context";
import { Glass } from "@/components/ui/Glass";
import { Icon, type IconName } from "@/components/ui/Icon";
import { Tap } from "@/components/ui/Tap";
import { Display, Text } from "@/components/ui/Text";
import { useApp } from "@/lib/store";
import { colors } from "@/lib/theme";
import type { Thread } from "@/lib/types";
import { useDrawer } from "./SideDrawer";

const destinations: { label: string; icon: IconName; href: Href }[] = [
  { label: "History", icon: "time-outline", href: "/history" },
  { label: "Memory", icon: "sparkles-outline", href: "/memory" },
];

function threadIcon(t: Thread): IconName {
  if (t.mode === "research") return "telescope-outline";
  if (t.incognito) return "eye-off-outline";
  return "chatbubble-outline";
}

/** Drawer contents: destinations, recent chats, then settings and a new-chat button pinned to the bottom. */
export function NavPanel() {
  const insets = useSafeAreaInsets();
  const { close } = useDrawer();
  const threads = useApp((s) => s.threads);
  const activeId = useApp((s) => s.activeThreadId);
  const streamingId = useApp((s) => s.streaming?.threadId);
  const openThread = useApp((s) => s.openThread);
  const newChat = useApp((s) => s.newChat);

  const recents = useMemo(
    () => Object.values(threads).sort((a, b) => b.updatedAt - a.updatedAt).slice(0, 6),
    [threads]
  );

  const go = (href: Href) => {
    close();
    router.push(href);
  };

  return (
    <View className="flex-1" style={{ paddingTop: insets.top + 10 }}>
      <View className="flex-row items-center justify-between pl-5 pr-4">
        <Display className="text-[26px] leading-8">Atlas</Display>
        <Tap accessibilityRole="button" accessibilityLabel="Search chats" onPress={() => go("/history?search=1")}>
          <Glass radius={24} interactive>
            <View className="h-12 w-12 items-center justify-center">
              <Icon name="search" size={21} />
            </View>
          </Glass>
        </Tap>
      </View>

      <ScrollView className="flex-1" contentContainerStyle={{ paddingHorizontal: 8, paddingTop: 20, paddingBottom: 16 }}>
        {destinations.map((d) => (
          <Tap
            key={d.label}
            accessibilityRole="link"
            onPress={() => go(d.href)}
            className="flex-row items-center gap-4 rounded-2xl px-3 py-3"
          >
            <Icon name={d.icon} size={22} color={colors.text} />
            <Text className="text-[18px] leading-6">{d.label}</Text>
          </Tap>
        ))}

        <Text muted weight="medium" className="mb-1.5 mt-6 px-3 text-[15px]">
          Recents
        </Text>
        {recents.length === 0 ? (
          <Text className="px-3 py-2 text-[15px] text-ink-faint">Your chats will show up here.</Text>
        ) : null}
        {recents.map((t) => {
          const active = t.id === activeId;
          return (
            <Tap
              key={t.id}
              accessibilityRole="button"
              accessibilityState={{ selected: active }}
              onPress={() => {
                openThread(t.id);
                close();
              }}
              className={`flex-row items-center gap-4 rounded-2xl px-3 py-3 ${active ? "bg-white/10" : ""}`}
            >
              <Icon name={threadIcon(t)} size={20} color={active ? colors.text : colors.textMuted} />
              <Text className="flex-1 text-[17px] leading-6" numberOfLines={1}>
                {t.title}
              </Text>
              {streamingId === t.id ? (
                <View accessibilityLabel="Replying" className="h-2 w-2 rounded-full bg-primary" />
              ) : null}
            </Tap>
          );
        })}
        <Tap
          accessibilityRole="link"
          onPress={() => go("/history")}
          className="flex-row items-center gap-1 self-start rounded-2xl px-3 py-3"
        >
          <Text muted className="text-[16px]">
            View all
          </Text>
          <Icon name="chevron-forward" size={16} color={colors.textMuted} />
        </Tap>
      </ScrollView>

      <View className="flex-row items-center justify-between px-4" style={{ paddingBottom: Math.max(insets.bottom, 12) + 4 }}>
        <Tap
          accessibilityRole="button"
          accessibilityLabel="Settings"
          onPress={() => go("/settings")}
          className="h-[52px] w-[52px] items-center justify-center rounded-full bg-raised"
        >
          <Icon name="settings-outline" size={22} />
        </Tap>
        <Tap
          haptic
          accessibilityRole="button"
          onPress={() => {
            newChat();
            close();
          }}
          className="h-[52px] flex-row items-center gap-2 rounded-full bg-ink pl-5 pr-6"
        >
          <Icon name="add" size={22} color="#000" />
          <Text weight="bold" className="text-[17px] text-black">
            New chat
          </Text>
        </Tap>
      </View>
    </View>
  );
}

import { router } from "expo-router";

/** Back to the previous screen, or to Chat when a page was opened directly (web deep link). */
export function goBack(): void {
  if (router.canGoBack()) router.back();
  else router.replace("/");
}

import type { ReactNode } from "react";
import { View } from "react-native";
import { goBack } from "@/lib/nav";
import { Glass } from "./Glass";
import { Icon } from "./Icon";
import { Tap } from "./Tap";
import { Display, Text } from "./Text";

/** Back button row, then a large title — the header for pages opened from the side menu. */
export function ScreenHeader({ title, subtitle, right }: { title: string; subtitle?: string; right?: ReactNode }) {
  return (
    <View className="pb-4">
      <View className="mb-4 flex-row items-center justify-between">
        <Tap accessibilityRole="button" accessibilityLabel="Back" onPress={goBack}>
          <Glass radius={20} interactive>
            <View className="h-10 w-10 items-center justify-center">
              <Icon name="chevron-back" size={20} />
            </View>
          </Glass>
        </Tap>
        {right ? <View className="flex-row gap-2">{right}</View> : null}
      </View>
      <Display accessibilityRole="header" className="text-[30px] leading-[38px]">
        {title}
      </Display>
      {subtitle ? (
        <Text muted className="mt-0.5 text-sm leading-5">
          {subtitle}
        </Text>
      ) : null}
    </View>
  );
}

/** Inset grouped list section — the iOS Settings pattern on `surface`. */
export function Group({ label, footer, children }: { label?: string; footer?: string; children: ReactNode }) {
  return (
    <View className="mb-6">
      {label ? (
        <Text weight="bold" muted className="mb-2 px-4 text-[13px]">
          {label}
        </Text>
      ) : null}
      <View className="overflow-hidden rounded-3xl bg-card">{children}</View>
      {footer ? <Text className="mt-2 px-4 text-xs leading-4 text-ink-faint">{footer}</Text> : null}
    </View>
  );
}

