import {
  Easing,
  FadeIn,
  FadeInDown,
  FadeOut,
  LinearTransition,
  ZoomIn,
  ZoomOut,
} from "react-native-reanimated";

/**
 * One motion vocabulary for the whole app. Layout animations below respect the system
 * Reduce Motion setting automatically; hand-rolled ones check useReducedMotion().
 */
export const springs = {
  /** Press feedback, toggles, thumbs — quick and settled. */
  snappy: { damping: 20, stiffness: 380, mass: 0.6 },
  /** Things travelling a distance — drawer, sheets, indicators. */
  glide: { damping: 26, stiffness: 240, mass: 0.9 },
};

const easeOut = Easing.out(Easing.cubic);

/** Section entrance when a page opens: rise and fade, staggered by position (capped so long pages don't crawl). */
export const enterUp = (index = 0) =>
  FadeInDown.duration(360)
    .delay(30 + Math.min(index, 10) * 45)
    .easing(easeOut)
    .withInitialValues({ opacity: 0, transform: [{ translateY: 14 }] });

export const fadeIn = FadeIn.duration(220);
export const fadeOut = FadeOut.duration(140);

/** Siblings sliding into the space left by an added or removed item. */
export const reflow = LinearTransition.springify().damping(26).stiffness(260);

/** Small controls that appear and disappear in place (send ↔ mic ↔ stop, jump-to-latest). */
export const popIn = ZoomIn.springify().damping(15).stiffness(320);
export const popOut = ZoomOut.duration(110);

/** Your message rising out of the composer. */
export const bubbleIn = FadeInDown.springify().damping(18).stiffness(220);
/** Assistant replies have no bubble, so they simply fade up into place. */
export const replyIn = FadeIn.duration(320).easing(easeOut);

import * as Haptics from "expo-haptics";
import type { ComponentProps } from "react";
import { Platform, Pressable, type StyleProp, type ViewStyle } from "react-native";
import Animated, {
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSpring,
  withTiming,
} from "react-native-reanimated";
import { springs } from "@/lib/motion";

const AnimatedPressable = Animated.createAnimatedComponent(Pressable);

type Props = Omit<ComponentProps<typeof Pressable>, "style"> & {
  haptic?: boolean;
  style?: StyleProp<ViewStyle>;
};

/** Squeeze in pixels at full press — the same felt depth for a 36px button and a full-width row. */
const SQUEEZE_PX = 10;
const MAX_SQUEEZE = 0.06;

/**
 * Pressable that squeezes and dims under the finger, then springs back on release.
 * Optional light haptic on iOS.
 */
export function Tap({ haptic, onPress, onPressIn, onPressOut, onLayout, style, ...rest }: Props) {
  const pressed = useSharedValue(0);
  const width = useSharedValue(0);
  const reduced = useReducedMotion();
  const maxSqueeze = reduced ? 0 : MAX_SQUEEZE;

  const feedback = useAnimatedStyle(() => {
    const squeeze = Math.min(maxSqueeze, SQUEEZE_PX / Math.max(width.get(), 1));
    return {
      opacity: 1 - pressed.get() * 0.28,
      transform: [{ scale: 1 - pressed.get() * squeeze }],
    };
  });

  return (
    <AnimatedPressable
      {...rest}
      onLayout={(e) => {
        width.set(e.nativeEvent.layout.width);
        onLayout?.(e);
      }}
      onPressIn={(e) => {
        pressed.set(withTiming(1, { duration: 80 }));
        onPressIn?.(e);
      }}
      onPressOut={(e) => {
        pressed.set(withSpring(0, springs.snappy));
        onPressOut?.(e);
      }}
      onPress={(e) => {
        if (haptic && Platform.OS === "ios") void Haptics.selectionAsync();
        onPress?.(e);
      }}
      style={[style, feedback]}
    />
  );
}

import { useEffect, useState } from "react";
import { View } from "react-native";
import Animated, {
  useAnimatedStyle,
  useReducedMotion,
  useSharedValue,
  withSpring,
} from "react-native-reanimated";
import { springs } from "@/lib/motion";
import { Tap } from "./Tap";
import { Text } from "./Text";

type Option<T extends string> = { value: T; label: string };

const PAD = 4;

/** Pill segmented control. The selection thumb slides between options instead of jumping. */
export function Segmented<T extends string>({
  options,
  value,
  onChange,
  accessibilityLabel,
}: {
  options: Option<T>[];
  value: T;
  onChange: (v: T) => void;
  accessibilityLabel?: string;
}) {
  const index = Math.max(0, options.findIndex((o) => o.value === value));
  const [width, setWidth] = useState(0);
  const position = useSharedValue(index);
  const reduced = useReducedMotion();
  const segment = width > 0 ? (width - PAD * 2) / options.length : 0;

  useEffect(() => {
    position.set(reduced ? index : withSpring(index, springs.glide));
  }, [index, reduced, position]);

  const thumb = useAnimatedStyle(() => ({
    width: segment,
    transform: [{ translateX: position.get() * segment }],
  }));

  return (
    <View
      accessibilityRole="radiogroup"
      accessibilityLabel={accessibilityLabel}
      onLayout={(e) => setWidth(e.nativeEvent.layout.width)}
      className="flex-row rounded-full bg-raised p-1"
    >
      {segment > 0 ? (
        <Animated.View
          pointerEvents="none"
          style={[{ position: "absolute", top: PAD, bottom: PAD, left: PAD, borderRadius: 999, backgroundColor: "#3F3F46" }, thumb]}
        />
      ) : null}
      {options.map((o) => {
        const active = o.value === value;
        return (
          <Tap
            key={o.value}
            haptic
            accessibilityRole="radio"
            accessibilityState={{ selected: active }}
            onPress={() => onChange(o.value)}
            className={`flex-1 items-center rounded-full px-3 py-1.5 ${active && segment === 0 ? "bg-[#3F3F46]" : ""}`}
          >
            <Text weight={active ? "bold" : "medium"} muted={!active} className="text-sm" numberOfLines={1}>
              {o.label}
            </Text>
          </Tap>
        );
      })}
    </View>
  );
}

